/**
 * Code Builder — assembles generated code from specs and templates.
 *
 * @module gen/code-builder
 */

import { TemplateEngine, BUILTIN_TEMPLATES, RenderOptions } from './template-engine.js';
import { CodeSpec, SpecProperty, SpecMethod } from './spec-parser.js';

/** Generated code output */
export interface GeneratedCode {
  /** Generated file content */
  content: string;
  /** Suggested filename */
  filename: string;
  /** Programming language */
  language: string;
  /** Imports section */
  imports?: string;
  /** Main code section */
  main: string;
  /** Test code (if generated) */
  tests?: string;
}

/** Builder options */
export interface BuilderOptions {
  /** Include JSDoc comments */
  includeDocs?: boolean;
  /** Include test generation */
  includeTests?: boolean;
  /** Custom code style preferences */
  style?: CodeStyle;
}

/** Code style preferences */
export interface CodeStyle {
  /** Use semicolons */
  semicolons?: boolean;
  /** Use single quotes */
  singleQuotes?: boolean;
  /** Indent size */
  indentSize?: number;
  /** Add trailing newline */
  trailingNewline?: boolean;
}

/**
 * Code Builder.
 * Assembles code from structured specifications and templates.
 */
export class CodeBuilder {
  private engine: TemplateEngine;
  private options: Required<BuilderOptions>;

  constructor(options: BuilderOptions = {}) {
    this.engine = new TemplateEngine();
    this.options = {
      includeDocs: options.includeDocs !== false,
      includeTests: options.includeTests || false,
      style: {
        semicolons: true,
        singleQuotes: true,
        indentSize: 2,
        trailingNewline: true,
        ...options.style,
      },
    };

    // Register built-in templates
    for (const template of BUILTIN_TEMPLATES) {
      this.engine.register(template);
    }
  }

  /**
   * Build code from a specification
   * @param spec - The code specification
   * @returns Generated code
   */
  build(spec: CodeSpec): GeneratedCode {
    switch (spec.kind) {
      case 'function': return this.buildFunction(spec);
      case 'class': return this.buildClass(spec);
      case 'interface': return this.buildInterface(spec);
      case 'type': return this.buildType(spec);
      case 'component': return this.buildComponent(spec);
      case 'api': return this.buildAPI(spec);
      case 'module': return this.buildModule(spec);
      default: return this.buildDefault(spec);
    }
  }

  /**
   * Build a function from spec
   */
  private buildFunction(spec: CodeSpec): GeneratedCode {
    const main = spec.methods?.[0];
    const params = (main?.parameters || spec.properties)
      .map((p) => {
        const optional = p.required === false ? '?' : '';
        const def = p.defaultValue ? ` = ${p.defaultValue}` : '';
        return `${p.name}${optional}: ${p.type}${def}`;
      })
      .join(', ');

    const returnType = main?.returnType || 'void';
    const asyncMod = main?.async ? 'async ' : '';

    let content = '';
    content += '// @generated by codemind

';

    if (this.options.includeDocs) {
      content += this.generateJSDoc(spec) + '
';
    }
    content += `${asyncMod}function ${spec.name}(${params}): ${returnType} {
`;
    content += '  // TODO: implement
';
    content += '}
';

    if (this.options.style.trailingNewline) {
      content += '
';
    }

    return {
      content,
      filename: `${spec.name}.ts`,
      language: spec.language,
      main: content,
    };
  }

  /**
   * Build a class from spec
   */
  private buildClass(spec: CodeSpec): GeneratedCode {
    let content = '';
    content += '// @generated by codemind

';

    if (this.options.includeDocs) {
      content += this.generateJSDoc(spec) + '
';
    }

    content += `class ${spec.name} {
`;

    // Properties
    for (const prop of spec.properties) {
      if (this.options.includeDocs && prop.description) {
        content += `  /** ${prop.description} */
`;
      }
      const def = prop.defaultValue ? ` = ${prop.defaultValue}` : '';
      content += `  ${prop.name}: ${prop.type}${def};
`;
    }

    if (spec.properties.length > 0) content += '
';

    // Constructor
    if (spec.properties.length > 0) {
      content += '  constructor() {
';
      for (const prop of spec.properties) {
        if (prop.defaultValue) {
          content += `    this.${prop.name} = ${prop.defaultValue};
`;
        }
      }
      content += '  }

';
    }

    // Methods
    for (const method of spec.methods || []) {
      if (this.options.includeDocs && method.description) {
        content += `  /** ${method.description} */
`;
      }
      const params = method.parameters
        .map((p) => `${p.name}: ${p.type}`)
        .join(', ');
      const ret = method.returnType ? `: ${method.returnType}` : '';
      const asyncMod = method.async ? 'async ' : '';

      content += `  ${asyncMod}${method.name}(${params})${ret} {
`;
      content += '    // TODO: implement
';
      content += '  }

';
    }

    content += '}
';

    if (this.options.style.trailingNewline) content += '
';

    return {
      content,
      filename: `${spec.name}.${this.getLangExt(spec.language)}`,
      language: spec.language,
      main: content,
    };
  }

  /**
   * Build an interface from spec
   */
  private buildInterface(spec: CodeSpec): GeneratedCode {
    let content = '';

    if (this.options.includeDocs) {
      content += this.generateJSDoc(spec) + '
';
    }

    content += `interface ${spec.name} {
`;

    for (const prop of spec.properties) {
      if (this.options.includeDocs && prop.description) {
        content += `  /** ${prop.description} */
`;
      }
      const optional = prop.required === false ? '?' : '';
      content += `  ${prop.name}${optional}: ${prop.type};
`;
    }

    content += '}
';

    return { content, filename: `${spec.name}.ts`, language: spec.language, main: content };
  }

  /**
   * Build a type alias
   */
  private buildType(spec: CodeSpec): GeneratedCode {
    let content = '';
    content += this.options.includeDocs ? this.generateJSDoc(spec) + '
' : '';

    const props = spec.properties.map((p) => `${p.name}: ${p.type}`).join('; ');
    content += `type ${spec.name} = { ${props} };
`;

    return { content, filename: `${spec.name}.ts`, language: spec.language, main: content };
  }

  /**
   * Build a component
   */
  private buildComponent(spec: CodeSpec): GeneratedCode {
    const props = spec.properties
      .map((p) => `  ${p.name}${p.required !== false ? '' : '?'}: ${p.type};`)
      .join('
');

    let content = '';

    if (this.options.includeDocs) {
      content += `/**
 * ${spec.description || spec.name} Component
 */
`;
    }

    content += `interface ${spec.name}Props {
${props}
}

`;
    content += `export function ${spec.name}(props: ${spec.name}Props): JSX.Element {
`;
    content += `  // TODO: implement
`;
    content += `  return <div></div>;
`;
    content += '}
';

    return {
      content,
      filename: `${spec.name}.tsx`,
      language: 'typescript',
      main: content,
    };
  }

  /**
   * Build API route/endpoint
   */
  private buildAPI(spec: CodeSpec): GeneratedCode {
    let content = '';

    if (this.options.includeDocs) {
      content += this.generateJSDoc(spec) + '
';
    }

    const params = spec.properties
      .filter((p) => p.required)
      .map((p) => `${p.name}: ${p.type}`)
      .join(', ');

    content += `export async function ${spec.name}(req: Request${params ? ', ' + params : ''}): Promise<Response> {
`;
    content += '  try {
';
    content += '    // TODO: implement
';
    content += '    return new Response(JSON.stringify({ ok: true }), {
';
    content += "      headers: { 'Content-Type': 'application/json' },
";
    content += '    });
';
    content += '  } catch (error) {
';
    content += "    return new Response(JSON.stringify({ error: 'Internal error' }), { status: 500 });
";
    content += '  }
';
    content += '}
';

    return {
      content,
      filename: `${spec.name}.ts`,
      language: spec.language,
      main: content,
    };
  }

  /**
   * Build a module
   */
  private buildModule(spec: CodeSpec): GeneratedCode {
    let content = '';
    content += `/**
 * ${spec.description || spec.name}
 */
`;
    content += `export * from './types.js';
`;
    content += `export * from './${spec.name}.js';
`;

    return { content, filename: 'index.ts', language: spec.language, main: content };
  }

  /**
   * Default fallback generation
   */
  private buildDefault(spec: CodeSpec): GeneratedCode {
    return this.buildFunction(spec);
  }

  /**
   * Generate JSDoc comment block
   */
  private generateJSDoc(spec: CodeSpec): string {
    const lines: string[] = [];
    lines.push('/**');
    lines.push(` * ${spec.description || spec.name}`);
    lines.push(' *');

    for (const prop of spec.properties) {
      if (prop.description) {
        lines.push(` * @param ${prop.name} - ${prop.description}`);
      }
    }

    for (const method of spec.methods || []) {
      if (method.description) {
        lines.push(` * @method ${method.name} - ${method.description}`);
      }
    }

    lines.push(' */');
    return lines.join('
');
  }

  /**
   * Get file extension for language
   */
  private getLangExt(lang: string): string {
    const map: Record<string, string> = {
      typescript: 'ts',
      javascript: 'js',
      python: 'py',
      rust: 'rs',
      go: 'go',
      java: 'java',
    };
    return map[lang] || 'ts';
  }

  /**
   * Register a custom template
   */
  registerTemplate(template: Parameters<TemplateEngine['register']>[0]): void {
    this.engine.register(template);
  }

  /**
   * Get the template engine instance
   */
  getTemplateEngine(): TemplateEngine {
    return this.engine;
  }
}
